declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
 value : DWORD;
END_VAR
VAR_OUTPUT
 hasChanged : BOOL;
 hasRisingEdges : BOOL;
 risingBits : DWORD;
 noOfRisingBits : USINT;
 hasFallingEdges : BOOL;
 fallingBits : DWORD;
 noOfFallingBits : USINT;
END_VAR
VAR
 prev : DWORD := DWORD#0;
END_VAR

implementation:
risingBits := value AND NOT prev;
fallingBits := prev AND NOT value;
hasChanged := value <> prev;
hasRisingEdges := risingBits <> DWORD#0;
hasFallingEdges := fallingBits <> DWORD#0;
noOfRisingBits := USINT#0;
noOfFallingBits := USINT#0;
prev := value;
